      SUBROUTINE SKETCH(NN)CC     DETERMINE WHICH PARAMETERS ARE USED TO DESCRIBE ELEMENTCC ----------------------------------------------------------------------      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA0B.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1B.CIN'      INCLUDE 'DATA2D.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'LIMITS.CIN'      INCLUDE 'NELMS.CIN'C ---------------------------------------------------------------------      INTEGER         TYPEN      INTEGER         NELMX(NELMCT)      EXTERNAL        IDATA      DATA NELMX /99,99,99,99,99, 7,99,99,99,11,     1            99,99, 2,99,99, 2,99,99,99,99,     2            99, 3, 5, 1,99,99,99,99,99,99,     3             1, 2, 2,99,99,99, 4,20,99,99,     4            99,99,99, 1,99,99,99,99/C      DO 12 J = 1, 25      IPTOJ(J) = 0   12 CONTINUEC      ICT = 0      II = ISTOR(NN)      TYPEN = IABS(IDATA(II))      IF (TYPEN .LE. NELMCT) NMAX = NELMX(TYPEN)      IF (TYPEN .EQ. 16 .AND. DATA(II+1) .LT. 0) NMAX = 3      IF (TYPEN .EQ. 24 .AND. (IDATA(II+1) .EQ. 3     1    .OR. IDATA(II+1) .EQ. 4)) NMAX = 3      IF (TYPEN .GE. 50 .AND. TYPEN .LE. 52) NMAX = NPHST      IF (TYPEN .EQ. 53) NMAX = NPFLG      IF (TYPEN .EQ. 60) NMAX = NPDCAY      IF (TYPEN .GE. 78 .AND. TYPEN .LE. 82) NMAX = 0      IF (NMAX .EQ. 99) NMAX = NELMS(TYPEN)      IF (NMAX .EQ. 0) GO TO 20      IF (TYPEN .EQ. 14) THEN        IF (II+30 .LE. IDLIM) THEN          IF (IDATA(II+30) .NE. 0) NMAX = 29        ENDIF        IF (II+8 .LE. IDLIM) THEN          IF (IDATA(II+8) .NE. 0) NMAX = 7        ENDIF        NPARMS = NMAX      ENDIF      IF (TYPEN .NE. 14) THEN        NMAX = MIN0(NMAX,25)      ENDIF      DESCR = NDESCR(NN)      DO 15 J = 1, NMAX      INDEX = MOD(DESCR,2)      IF (INDEX .NE. 0) THEN        ICT = ICT + 1        IPTOJ(J) = ICT      ENDIF      DESCR = DESCR/2      IF (DESCR .EQ. 0) GO TO 20   15 CONTINUE   20 IF (TYPEN .NE. 14) THEN        NPARMS = ICT      ELSE        NPARMS = NMAX      ENDIF      IF (TYPEN .EQ. 30) THEN        IF (TIE(II+1) .EQ. 99) NPARMS = 21      ENDIF   30 CONTINUE      RETURN      END